insert into public.world_item_catalog(item_id, item_name, category, tier, description, stackable, required_stats, minimum_level, rarity, acquisition_difficulty, drop_rate_modifier, equipment_traits, tradeable, reference_price, stack_size)
select x.item_id, x.item_name, x.category, x.tier, x.description, x.stackable, x.required_stats, x.minimum_level, x.rarity, x.acquisition_difficulty, x.drop_rate_modifier, x.equipment_traits, x.tradeable, x.reference_price, x.stack_size from jsonb_to_recordset($J$[{"item_id":"hf_mz_forge_brazier","item_name":"명석 무쇠 화로","category":"furniture","tier":5,"description":"명장 가구 · 화로. 명소 재료로 짓는 별채 가구입니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{"hk":"mz_forge_brazier","kind":"floor","w":1,"d":1,"top":0,"cat":"화로","grade":5},"tradeable":true,"reference_price":2400,"stack_size":1},{"item_id":"hf_mz_mother_chest","item_name":"명목 자개 반닫이","category":"furniture","tier":5,"description":"명장 가구 · 수납. 명소 재료로 짓는 별채 가구입니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{"hk":"mz_mother_chest","kind":"floor","w":2,"d":1,"top":0.92,"cat":"수납","grade":5},"tradeable":true,"reference_price":2400,"stack_size":1},{"item_id":"hf_mz_window_screen","item_name":"창가 풍경 병풍","category":"furniture","tier":5,"description":"명장 가구 · 병풍. 명소 재료로 짓는 별채 가구입니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{"hk":"mz_window_screen","kind":"floor","w":2,"d":1,"top":0,"cat":"병풍","grade":5},"tradeable":true,"reference_price":2400,"stack_size":1},{"item_id":"hf_mz_seal_censer","item_name":"봉인 향로","category":"furniture","tier":5,"description":"명장 가구 · 소품. 명소 재료로 짓는 별채 가구입니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{"hk":"mz_seal_censer","kind":"floor","w":1,"d":1,"top":0,"cat":"소품"