고 마지막 방에서만 나옵니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{"hk":"bj_name_chest","kind":"floor","w":1,"d":1,"top":0,"cat":"수납","grade":5},"tradeable":false,"reference_price":2400,"stack_size":1},{"item_id":"hf_bj_vault_gate","item_name":"비장고 문짝 장식","category":"furniture","tier":5,"description":"비장고 가구 · 문. 비장고 마지막 방에서만 나옵니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{"hk":"bj_vault_gate","kind":"wall","wall":"deco","ww":1.6,"wh":36,"cat":"문","grade":5},"tradeable":false,"reference_price":2400,"stack_size":1},{"item_id":"hf_bj_map_frame","item_name":"옛 비장도 액자","category":"furniture","tier":5,"description":"비장고 가구 · 지도. 비장고 마지막 방에서만 나옵니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{"hk":"bj_map_frame","kind":"wall","wall":"deco","ww":2.2,"wh":26,"cat":"지도","grade":5},"tradeable":false,"reference_price":2400,"stack_size":1}]$J$::jsonb) as x(item_id text, item_name text, category text, tier int, description text, stackable boolean, required_stats jsonb, minimum_level int, rarity text, acquisition_difficulty int, drop_rate_modifier numeric, equipment_traits jsonb, tradeable boolean, reference_price bigint, stack_size int)
on conflict (item_id) do update set item_name = excluded.item_name, category = excluded.category, tier = excluded.tier, description = excluded.description,
  equipment_traits = excluded.equipment_traits, tradeable = excluded.tradeable, stack_size = excluded.stack_size;

insert into public.world_crafting_recipes(recipe_id, recipe_name, output_item, output_qty, ingredients, required_tool_tier, required_location, description, minimum_level, recipe_difficulty, quality_bonus, required_skill, required_skill_rank, craft_field)
select x.recipe_id, x.recipe_name, x.output_item, x.output_qty, x.ingredients, x.required_tool_tier, x.required_location, x.description, x.minimum_level, x.recipe_difficulty, x.quality_bonus, x.required_skill, x.required_skill_rank, x.craft_field from jsonb_to_recordset($J$[{"recipe_id":"r_hf_mz_forge_brazier","recipe_name":"명석 무쇠 화로 만들기","output_item":"hf_mz_forge_brazier","output_qty":1,"ingredients":{"mz_stone_j":2,"mz_stone":4,"iron_ingot":6},"required_tool_tier":1,"required_location":null,"description":"별채에 놓을 명석 무쇠 화로을(를) 짓는다. 명장 제작법(40단계).","minimum_level":38,"recipe_difficulty":5,"quality_bonus":0,"required_skill":"smithing","required_skill_rank":40,"craft_field":"smithing"},{"recipe_id":"r_hf_mz_mother_chest","recipe_name":"명목 자개 반닫이 만들기","output_item":"hf_mz_mother_chest","output_qty":1,"ingredients":{"mz_wood_j":2,"mz_wood":4,"lacquer":6},"required_tool_tier":1,"required_location":null,"description":"별채에 놓을 명목 자개 반닫이을(를) 짓는다. 명장 제작법(40단계).","minimum_level":38,"recipe_difficulty":5,"quality_bonus":0,"required_skill":"carpentry","required_skill_rank":40,"craft_field":"carpentry"},{"recipe_id":"r_hf_mz_window_screen","recipe_name":"창가 풍경 병풍 만들기","output_item":"hf_mz_window_screen","output_qty":1,"ingredients":{"mz_wood_j":1,"mz_stone_j":1,"mz_wood":3,"moonless_silk":2},"required_tool_tier":1,"required_location":null,"description":"별채에 놓을 창가 풍경 병풍을(를) 짓는다. 명장 제작법(40단계).","minimum_level":38,"recipe_difficulty":5,"quality_bonus":0,"required_skill":"artifice","required_skill_rank":40,"craft_field":"artifice"},{"recipe_id":"r_hf_mz_seal_censer","recipe_name":"봉인 향로 만들기","output_item":"hf_mz_seal_censer","output_qty":1,"ingredients":{"mz_herb_j":1,"mz_stone_j":1,"mz_stone":3,"inverted_incense":2},"required_tool_tier":1,"required_location":null,"description":"별채에 놓을 봉인 향로을(를) 짓는다. 명장 제작법(40단계).","minimum_level":38,"recipe_difficulty":5,"quality_bonus":0,"required_skill":"wardcraft","required_skill_rank":40,"craft_field":"sealing"},{"recipe_id":"r_hf_mz_herb_blind","recipe_name":"명초 수 놓은 대발 만들기","output_item":"hf_mz_herb_blind","output_qty":1,"ingredients":{"mz_herb_j":2,"mz_herb":4,"moonless_silk":2},"required_tool_tier":1,"required_location":null,"description":"별채에 놓을 명초 수 놓은 대발을(를) 짓는다. 명장 제작법(40단계).","minimum_level":38,"recipe_difficulty":5,"quality_bonus":0,"required_skill":"weaving","required_skill_rank":40,"craft_field":"weaving"},{"recipe_id":"r_hf_mz_stone_hide_mat","recipe_name":"명석 무늬 가죽 깔개 만들기","output_item":"hf_mz_stone_hide_mat","output_qty":1,"ingredients":{"mz_stone_j":2,"mz_stone":3,"reinforced_leather":3},"required_tool_tier":1,"required_location":null,"description":"별채에 놓을 명석 무늬 가죽 깔개을(를) 짓는다. 명장 제작법(40단계).","minimum_level":38,"recipe_difficulty":5,"quality_bonus":0,"required_skill":"leatherwork","required_skill_rank":40,"craft_field":"leatherwork"},{"recipe_id":"r_hf_mz_herb_cabinet","recipe_name":"명초 백자 약장 만들기","output_item":"hf_mz_herb_cabinet","output_qty":1,"ingredients":{"mz_herb_j":2,"mz_wood":3,"lacquer":4},"required_tool_tier":1,"required_location":null,"description":"별채에 놓을 명초 백자 약장을(를) 짓는다. 명장 제작법(40단계).","minimum_level":38,"recipe_difficulty":5,"quality_bonus":0,"required_skill":"alchemy","required_skill_rank":40,"craft_field":"alchemy"},{"recipe_id":"r_hf_mz_tea_table","recipe_name":"명초 다과상 만들기","output_item":"hf_mz_tea_table","output_qty":1,"ingredients":{"mz_herb_j":2,"mz_wood":3,"mz_herb":3},"required_tool_tier":1,"required_location":null,"description":"별채에 놓을 명초 다과상을(를) 짓는다. 명장 제작법(40단계).","minimum_level":38,"recipe_difficulty":5,"quality_bonus":0,"required_skill":"cooking","required_skill_rank":40,"craft_field":"cooking"}]$J$::jsonb) as x(recipe_id text, recipe_name text, output_item text, output_qty int, ingredients jsonb, required_tool_tier int, required_location text, description text, minimum_level int, recipe_difficulty int, quality_bonus int, required_skill text, required_skill_rank int, craft_field text)
on conflict (recipe_id) do update set recipe_name = excluded.recipe_name, output_item = excluded.output_item, ingredients = excluded.ingredients,
  minimum_level = excluded.minimum_level, required_skill = excluded.required_skill, required_skill_rank = excluded.required_skill_rank, craft_field = excluded.craft_field,
  description = excluded.description, recipe_difficulty = excluded.recipe_difficulty;

update public.world_item_catalog i set reference_price = greatest(2400, ceil(1.1 * (select sum(c.reference_price * v::int) from public.world_crafting_recipes r,
  jsonb_each_text(r.ingredients) e(k, v) join public.world_item_catalog c on c.item_id = e.k where r.output_item = i.item_id)))
 where i.item_id in (select output_item from public.world_crafting_recipes where recipe_id like 'r\_hf\_mz\_%');

update public.world_item_catalog i set reference_price = 4000 where i.item_id in (select 'hf_' || x from jsonb_array_elements_text($J$["bj_name_chest","bj_vault_gate","bj_map_frame"]$J$::jsonb) x);

do $c$ begin if (select count(*) from public.world_item_catalog where item_id like 'hf\_mz\_%' or item_id like 'hf\_bj\_%') <> 11 then raise exception '가구 물품 수가 맞지 않습니다'; end if; end $c$;

update public.world_app_meta set value = '20261117050000' where key = 'db_version';
